B.c1Y=new A.cV("wlan.fc.type_subtype == 0x03","Reassociation response")
B.c1p=new A.cV("wlan.fc.type_subtype == 0x0b","Authentication, the frame before the reassociation")
B.c1e=new A.cV("wlan.fc.type_subtype == 0x0c","Deauthentication, a roam that was not the client's idea")
B.c1H=new A.cV("wlan.tag.number == 55","Mobility Domain element, present when 802.11r Fast Transition is in play")
B.c1b=new A.cV("rtp.ssrc == 0x12345678 && wlan.fc.retry == 1","Retries on the one stream you are following")
